// Shape the LLM reply so the rest of the flow stays the same
const businessCase = $json.output
return {
  businessCase,
  inputSource: 'chat',
  chatRequestId: `openai-${Date.now()}`
};

// Generate timestamp for unique page titles
const timestamp = $now.toFormat('yyyy-MM-dd-HH-mm');
const businessCase = $('Format Chat Input').first().json.businessCase
const baPackage = $('1. Business Analyst Research').first().json.text;
const functionalSpec = $('2. Generate Functional Specification').first().json.text;
const technicalSpec = $('3. Generate Technical Specification').first().json.text;
const mermaidScript = $('5. Generate Mermaid Architecture').first().json.text;
const jiraEpicKey = $('4. Create JIRA Epic').first().json.key;

// Create comprehensive Confluence page content
const pageTitle = `${timestamp} - Business Case Analysis: ${businessCase}`;

const pageBody = `
<h1>Business Case Analysis: ${businessCase}</h1>
<p><strong>Generated on:</strong> ${$now.toFormat('yyyy-MM-dd HH:mm:ss')}</p>
<p><strong>Related JIRA Epic:</strong> <a href="https://your-domain.atlassian.net/browse/${jiraEpicKey}">${jiraEpicKey}</a></p>

<h2>📋 Business Analyst Research Package</h2>
<div class="panel">
<div class="panelContent">
${baPackage.replace(/\n/g, '<br/>')}
</div>
</div>

<h2>📄 Functional Specification</h2>
<div class="panel">
<div class="panelContent">
${functionalSpec.replace(/\n/g, '<br/>')}
</div>
</div>

<h2>🔧 Technical Specification</h2>
<div class="panel">
<div class="panelContent">
${technicalSpec.replace(/\n/g, '<br/>')}
</div>
</div>

<h2>🏗️ System Architecture Diagram</h2>
<ac:structured-macro ac:name="mermaid">
  <ac:plain-text-body><![CDATA[
${mermaidScript}
  ]]></ac:plain-text-body>
</ac:structured-macro>

<h2>📊 Summary</h2>
<p>This comprehensive business case analysis was automatically generated and includes all necessary documentation for project initiation and development planning.</p>
`;

return {
  page_title: pageTitle,
  page_body: pageBody,
  business_case: businessCase,
  jira_epic_key: jiraEpicKey
};
